    if (x >= 1) return 1;
    if (x > (a + 1) / (a + b + 2)) return 1 - _ibeta(1 - x, b, a);
    var tiny = 1e-300, c = 1, d = 1 - (a + b) * x / (a + 1);
    if (Math.abs(d) < tiny) d = tiny;
    d = 1 / d;
